// An in-memory todo store.
function createStore() {
  const todos = [];
  let nextId = 1;

  return {
    /** Adds a todo and returns it. */
    add(title) {
      if (typeof title !== 'string' || title.trim() === '') {
        throw new TypeError('title must be a non-empty string');
      }
      const todo = { id: nextId++, title: title.trim(), done: false };
      todos.push(todo);
      return todo;
    },

    /** Marks a todo as done. Returns false when there is no such todo. */
    complete(id) {
      const todo = todos.find((t) => t.id === id);
      if (!todo) return false;
      todo.done = true;
      return true;
    },

    /** A copy of the todos, in the order they were added. */
    list() {
      return todos.map((t) => ({ ...t }));
    },
  };
}

module.exports = { createStore };

--- src/format.js ---
// Plain-text rendering of todos, one per line.
function formatList(todos) {
  return todos.map((t) => `[${t.done ? 'x' : ' '}] ${t.title}`).join('\n');
}

module.exports = { formatList };

